const form = $('Form RFQ').first().json;
let ai = {};
try {
  ai = JSON.parse($json.choices[0].message.content);
} catch (e) {
  ai = { campi_mancanti: ['errore lettura AI'], riepilogo: 'Errore di lettura della risposta AI', bozza_risposta: '' };
}
const missing = Array.isArray(ai.campi_mancanti) ? ai.campi_mancanti : [];
const parts = String(form['Nome e cognome'] || '').trim().split(/\s+/);
return [{ json: {
  ...ai,
  nome: parts[0] || '',
  cognome: parts.slice(1).join(' '),
  email: form['Email'],
  azienda: form['Azienda'],
  descrizione: form['Descrizione della richiesta'],
  campi_mancanti: missing,
  completa: missing.length === 0
} }];

